1	// ivdr-wiki/src/data/progress.ts
2	import { useState, useCallback } from "react";
3	
4	export type DocStatus = "not_started" | "in_progress" | "done";
5	type ProgressMap = Record<string, DocStatus>;
6	
7	const storageKey = (certId: string) => `cert-progress-${certId}`;
8	
9	function loadProgress(certId: string): ProgressMap {
10	  try {
11	    return JSON.parse(localStorage.getItem(storageKey(certId)) ?? "{}");
12	  } catch {
13	    return {};
14	  }
15	}
16	
17	function saveProgress(certId: string, map: ProgressMap) {
18	  localStorage.setItem(storageKey(certId), JSON.stringify(map));
19	}
20	
21	export function useProgress(certId: "ivdr" | "iso13485") {
22	  const [progress, setProgress] = useState<ProgressMap>(() => loadProgress(certId));
23	
24	  const setStatus = useCallback(
25	    (docId: string, status: DocStatus) => {
26	      setProgress((prev) => {
27	        const next = { ...prev, [docId]: status };
28	        saveProgress(certId, next);
29	        return next;
30	      });
31	    },
32	    [certId],
33	  );
34	
35	  const getStatus = useCallback(
36	    (docId: string): DocStatus => progress[docId] ?? "not_started",
37	    [progress],
38	  );
39	
40	  const countByStatus = useCallback(
41	    (docIds: string[]) => {
42	      let done = 0, inProgress = 0;
43	      for (const id of docIds) {
44	        const s = progress[id] ?? "not_started";
45	        if (s === "done") done++;
46	        else if (s === "in_progress") inProgress++;
47	      }
48	      return { done, inProgress, total: docIds.length };
49	    },
50	    [progress],
51	  );
52	
53	  return { getStatus, setStatus, countByStatus };
54	}
55	
56	export const STATUS_LABEL: Record<DocStatus, string> = {
57	  not_started: "미작성",
58	  in_progress: "작성 중",
59	  done: "완료",
60	};
61	
62	export const STATUS_NEXT: Record<DocStatus, DocStatus> = {
63	  not_started: "in_progress",
64	  in_progress: "done",
65	  done: "not_started",
66	};
67	
68	export const STATUS_COLOR: Record<DocStatus, string> = {
69	  not_started: "var(--text-subtle)",
70	  in_progress: "var(--warning)",
71	  done: "var(--success)",
72	};
